import { renderHook, waitFor, act } from '@testing-library/react'
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { useBooks } from './useBooks'
import * as api from '../api'

describe('useBooks', () => {
  beforeEach(() => {
    vi.restoreAllMocks()
  })

  it('starts in loading state before data resolves', () => {
    vi.spyOn(api, 'getBooks').mockReturnValue(new Promise(() => {})) // never resolves
    const { result } = renderHook(() => useBooks())
    expect(result.current.loading).toBe(true)
    expect(result.current.data).toBeUndefined()
    expect(result.current.error).toBeUndefined()
  })

  it('sets data and clears loading when getBooks resolves', async () => {
    const books = [{ id: 1, title: 'Dune' }, { id: 2, title: 'Neuromancer' }]
    vi.spyOn(api, 'getBooks').mockResolvedValue(books)

    const { result } = renderHook(() => useBooks())

    await waitFor(() => expect(result.current.loading).toBe(false))

    expect(result.current.data).toEqual(books)
    expect(result.current.error).toBeUndefined()
  })

  it('sets error and clears loading when getBooks rejects', async () => {
    const err = new Error('fetch failed')
    vi.spyOn(api, 'getBooks').mockRejectedValue(err)

    const { result } = renderHook(() => useBooks())

    await waitFor(() => expect(result.current.loading).toBe(false))

    expect(result.current.error).toBe(err)
    expect(result.current.data).toBeUndefined()
  })

  it('returns an empty array when getBooks resolves with no books', async () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue([])

    const { result } = renderHook(() => useBooks())

    await waitFor(() => expect(result.current.loading).toBe(false))

    expect(result.current.data).toEqual([])
    expect(result.current.error).toBeUndefined()
  })

  it('calls getBooks exactly once on mount', async () => {
    const spy = vi.spyOn(api, 'getBooks').mockResolvedValue([])

    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))

    expect(spy).toHaveBeenCalledTimes(1)
  })

  it('does not call getBooks again on re-render', async () => {
    const spy = vi.spyOn(api, 'getBooks').mockResolvedValue([])

    const { result, rerender } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))

    rerender()
    rerender()

    expect(spy).toHaveBeenCalledTimes(1)
  })

  it('does not update state after unmount (no unhandled state update warning)', async () => {
    let resolve!: (v: unknown[]) => void
    vi.spyOn(api, 'getBooks').mockReturnValue(
      new Promise((res) => { resolve = res })
    )

    const { result, unmount } = renderHook(() => useBooks())
    expect(result.current.loading).toBe(true)

    await act(async () => {
      unmount()
      resolve([{ id: 1, title: 'Late Book' }])
    })
    // If state update after unmount were unguarded the hook would warn/throw.
    // Reaching here without error confirms the guard is in place.
  })
})
